709	// GetPeriodClose returns one stored period close.
710	func (s *Service) GetPeriodClose(id string) (any, error) {
711		return s.store.View(func(state *State) (any, error) {
712			close, found := state.PeriodCloses[id]
713			if !found {
714				return nil, NotFoundError("period close not found")
715			}
716			return close, nil
717		})
718	}
