720	// CreateAdjustment posts an adjustment journal into a closed period through
721	// its close. The voucher follows every ordinary journal rule and additionally
722	// requires a memo and a date inside the closed period.
723	func (s *Service) CreateAdjustment(closeID string, body []byte, key string) (any, error) {
724		var request createJournalRequest
725		if err := decodeObject(body, &request); err != nil {
726			return nil, err
727		}
728		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
729		if err != nil {
730			return nil, err
731		}
732		return s.runIdempotent(key, "create-adjustment:"+closeID+":"+id, func(state *State) (any, error) {
733			close, found := state.PeriodCloses[closeID]
734			if !found {
735				return nil, NotFoundError("period close not found")
736			}
737			if memo == "" {
738				return nil, ValidationError("adjustment memo required")
739			}
740			if date < close.Period.Start || date > close.Period.End {
741				return nil, ValidationError("adjustment date outside period")
742			}
743			if _, found := state.Journals[id]; found {
744				return nil, ConflictError("journal exists")
745			}
746			journal, err := s.buildJournal(state, &request, id, date, memo)
747			if err != nil {
748				return nil, err
749			}
750			state.Journals[id] = journal
751			close.AdjustmentJournalIDs = append(close.AdjustmentJournalIDs, id)
752			close.AdjustmentCount = len(close.AdjustmentJournalIDs)
753			return journal, nil
754		})
755	}
756	
757	func (s *Service) buildJournalLine(state *State, raw *journalLineRequest, index int, date string) (*JournalLine, error) {
758		if raw == nil {
759			return nil, ValidationError("lines[%d] must be an object", index)
760		}
761		accountID, err := validateIdentifier(raw.AccountID, fmt.Sprintf("lines[%d].account_id", index))
762		if err != nil {
763			return nil, err
764		}
765		account, found := state.Accounts[accountID]
766		if !found {
767			return nil, ValidationError("lines[%d].account_id %s does not exist", index, accountID)
768		}
769		if raw.Side != "debit" && raw.Side != "credit" {
770			return nil, ValidationError("lines[%d].side must be debit or credit", index)
771		}
772		amount, err := validateAmount(raw.AmountMinor, fmt.Sprintf("lines[%d].amount_minor", index), false, false)
773		if err != nil {
774			return nil, err
775		}
776		currency, err := validateCurrency(raw.Currency, fmt.Sprintf("lines[%d].currency", index), false)
777		if err != nil {
778			return nil, err
779		}
780		if currency == "" {
781			currency = account.Currency
782		}
783		if currency != account.Currency {
784			return nil, ValidationError(
785				"lines[%d].currency %s must match the currency %s of account %s",
786				index, currency, account.Currency, accountID,
787			)
788		}
789		reference, err := validateText(raw.Reference, fmt.Sprintf("lines[%d].reference", index))
790		if err != nil {
791			return nil, err
792		}
793		numerator, denominator, source, err := s.resolveRate(state, currency, date, raw.Rate, fmt.Sprintf("lines[%d].rate", index))
794		if err != nil {
795			return nil, err
796		}
797		functional, err := convertMinor(amount, numerator, denominator)
798		if err != nil {
799			return nil, err
800		}
801		if functional < 1 {
802			return nil, ValidationError(
803				"lines[%d] converts to zero minor units in %s; use a larger amount or a finer exchange rate",
804				index, s.functionalCurrency,
805			)
806		}
807		return &JournalLine{
808			Index:                 index,
809			AccountID:             accountID,
810			Side:                  raw.Side,
811			AmountMinor:           amount,
812			Currency:              currency,
813			Rate:                  raw.Rate,
814			RateNumerator:         numerator,
815			RateDenominator:       denominator,
816			RateSource:            source,
817			FunctionalAmountMinor: functional,
818			Reference:             reference,
819		}, nil
820	}
821	
822	// resolveRate returns the exact fraction that converts one minor unit of
823	// currency into the functional currency for the given date.
824	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
825		if currency == s.functionalCurrency {
826			if declared == "" || declared == "1" {
827				return 1, 1, "identity", nil
828			}
829			numerator, denominator, err := parseRateFraction(declared, field)
830			if err != nil {
831				return 0, 0, "", err
832			}
833			if numerator != denominator {
834				return 0, 0, "", ValidationError(
835					"%s must be omitted or exactly 1 because %s is the functional currency",
836					field, currency,
837				)
838			}
839			return 1, 1, "identity", nil
840		}
841		if declared != "" {
842			numerator, denominator, err := parseRateFraction(declared, field)
843			if err != nil {
844				return 0, 0, "", err
845			}
846			return numerator, denominator, "declared", nil
847		}
848		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
849			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
850		}
851		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
852			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
853		}
854		return 0, 0, "", ValidationError(
855			"no %s/%s exchange rate snapshot exists on or before %s",
856			currency, s.functionalCurrency, date,
857		)
858	}
859	
860	type periodRequest struct {
861		Start string `json:"start"`
862		End   string `json:"end"`
863	}
864	
865	type statementLineRequest struct {
866		ID          string `json:"id"`
867		Date        string `json:"date"`
868		AmountMinor int64  `json:"amount_minor"`
869		Reference   string `json:"reference"`
870		Description string `json:"description"`
