20	// fixedClock makes every created_at value reproducible.
21	var fixedClock = time.Date(2024, 6, 1, 12, 0, 0, 0, time.UTC)
22	
23	type request struct {
24		method      string
25		path        string
26		key         string
27		body        string
28		contentType string
29		omitType    bool
30	}
31	
32	type client struct {
33		t      *testing.T
34		server *httptest.Server
35		keys   int
36	}
37	
38	func newClient(t *testing.T) *client {
39		t.Helper()
40		return newClientOn(t, filepath.Join(t.TempDir(), "ledger.db"))
41	}
42	
43	func newClientOn(t *testing.T, database string) *client {
44		t.Helper()
45		store, err := reconcore.OpenStore(database)
46		if err != nil {
47			t.Fatalf("open store: %v", err)
48		}
49		service, err := reconcore.NewService(store, "CNY", func() time.Time { return fixedClock })
50		if err != nil {
51			t.Fatalf("new service: %v", err)
52		}
53		server := httptest.NewServer(reconcore.NewServer(service))
54		t.Cleanup(server.Close)
55		return &client{t: t, server: server}
56	}
57	
58	func (c *client) send(r request) (int, string, map[string]any) {
59		c.t.Helper()
60		var body io.Reader
61		if r.body != "" {
62			body = bytes.NewBufferString(r.body)
63		}
64		httpRequest, err := http.NewRequest(r.method, c.server.URL+r.path, body)
65		if err != nil {
66			c.t.Fatalf("build request: %v", err)
67		}
68		if !r.omitType {
69			contentType := r.contentType
70			if contentType == "" {
71				contentType = "application/json"
72			}
73			httpRequest.Header.Set("Content-Type", contentType)
74		}
75		if r.key != "" {
76			httpRequest.Header.Set("Idempotency-Key", r.key)
77		}
78		response, err := c.server.Client().Do(httpRequest)
79		if err != nil {
80			c.t.Fatalf("%s %s: %v", r.method, r.path, err)
81		}
82		defer response.Body.Close()
83		raw, err := io.ReadAll(response.Body)
84		if err != nil {
85			c.t.Fatalf("read %s %s: %v", r.method, r.path, err)
86		}
87		decoded := map[string]any{}
88		if len(raw) > 0 {
89			if err := json.Unmarshal(raw, &decoded); err != nil {
90				c.t.Fatalf("%s %s returned non-object JSON %s", r.method, r.path, raw)
91			}
92		}
93		return response.StatusCode, string(raw), decoded
94	}
95	
96	func (c *client) post(path, body string) (int, string, map[string]any) {
97		c.keys++
98		return c.send(request{method: http.MethodPost, path: path, key: fmt.Sprintf("key-%03d", c.keys), body: body})
99	}
100	
101	func (c *client) get(path string) (int, string, map[string]any) {
102		return c.send(request{method: http.MethodGet, path: path})
103	}
104	
105	func (c *client) created(path, body string) map[string]any {
106		c.t.Helper()
107		status, raw, decoded := c.post(path, body)
108		if status != http.StatusCreated {
109			c.t.Fatalf("POST %s returned %d: %s", path, status, raw)
110		}
111		return decoded
112	}
113	
114	func (c *client) ok(path string) map[string]any {
115		c.t.Helper()
116		status, raw, decoded := c.get(path)
117		if status != http.StatusOK {
118			c.t.Fatalf("GET %s returned %d: %s", path, status, raw)
119		}
120		return decoded
121	}
122	
123	func (c *client) expect(r request, wantStatus int, wantCode, wantMessage string) {
124		c.t.Helper()
125		status, raw, decoded := c.send(r)
126		if status != wantStatus {
127			c.t.Fatalf("%s %s returned %d (%s), want %d", r.method, r.path, status, raw, wantStatus)
128		}
129		failure, ok := decoded["error"].(map[string]any)
130		if !ok {
131			c.t.Fatalf("%s %s did not return an error body: %s", r.method, r.path, raw)
132		}
133		if failure["code"] != wantCode {
134			c.t.Fatalf("%s %s error code is %v, want %s", r.method, r.path, failure["code"], wantCode)
135		}
136		message, _ := failure["message"].(string)
137		if wantMessage != "" && !strings.Contains(message, wantMessage) {
138			c.t.Fatalf("%s %s message %q does not mention %q", r.method, r.path, message, wantMessage)
139		}
140	}
