549	func TestReconciliationClassification(t *testing.T) {
550		client := newClient(t)
551		client.created("/accounts", accountBody("1100", "Bank", "asset", "CNY"))
552		client.created("/accounts", accountBody("4000", "Revenue", "revenue", "CNY"))
553		client.created("/accounts", accountBody("5000", "Expense", "expense", "CNY"))
554	
555		post := func(id, date string, bankSide string, amount int64, reference string) {
556			client.created("/journals", fmt.Sprintf(`{
557				"id":%q,"date":%q,
558				"lines":[
559					{"account_id":"1100","side":%q,"amount_minor":%d,"reference":%q},
560					{"account_id":"4000","side":%q,"amount_minor":%d,"reference":%q}
561				]}`,
562				id, date, bankSide, amount, reference,
563				map[string]string{"debit": "credit", "credit": "debit"}[bankSide], amount, reference))
564		}
565		post("jv-1", "2024-03-05", "debit", 100000, "INV-1")
566		post("jv-2", "2024-03-08", "credit", 50000, "INV-2")
567		post("jv-3", "2024-03-10", "debit", 25000, "INV-3")
568		post("jv-4", "2024-03-15", "credit", 12000, "INV-5")
569		post("jv-5", "2024-04-02", "debit", 999, "INV-6")
570	
571		client.created("/statements", `{
572			"id":"st-1","account_id":"1100","currency":"CNY",
573			"period":{"start":"2024-03-01","end":"2024-03-31"},
574			"opening_balance_minor":0,"closing_balance_minor":87000,
575			"lines":[
576				{"id":"s1","date":"2024-03-05","amount_minor":100000,"reference":"INV-1"},
577				{"id":"s2","date":"2024-03-06","amount_minor":-50000,"reference":"INV-2"},
578				{"id":"s3","date":"2024-03-10","amount_minor":30000,"reference":"INV-3"},
579				{"id":"s4","date":"2024-03-12","amount_minor":7000,"reference":"INV-4"}
580			]}`)
581	
582		reconciliation := client.created("/reconciliations", `{"id":"rec-1","statement_id":"st-1"}`)
583		if text(t, reconciliation, "status") != "differences_found" {
584			t.Fatalf("status is %v", reconciliation["status"])
585		}
586		if integer(t, reconciliation, "matched_count") != 3 {
587			t.Fatalf("matched count is %v", reconciliation["matched_count"])
588		}
589		if integer(t, reconciliation, "statement_line_count") != 4 || integer(t, reconciliation, "ledger_line_count") != 4 {
590			t.Fatalf("line counts are %v", reconciliation)
591		}
592		// The 2024-04-02 journal sits outside the period and must not be counted.
593		if integer(t, reconciliation, "statement_net_minor") != 87000 || integer(t, reconciliation, "ledger_net_minor") != 63000 {
594			t.Fatalf("nets are %v", reconciliation)
595		}
596		if integer(t, reconciliation, "difference_minor") != 24000 {
597			t.Fatalf("difference is %v", reconciliation["difference_minor"])
598		}
599		summary, ok := reconciliation["summary"].(map[string]any)
600		if !ok {
601			t.Fatalf("summary is %v", reconciliation["summary"])
602		}
603		for name, want := range map[string]int64{
604			"timing": 1, "amount_mismatch": 1, "missing_in_ledger": 1, "missing_in_statement": 1,
605		} {
606			if integer(t, summary, name) != want {
607				t.Fatalf("summary.%s is %v, want %d", name, summary[name], want)
608			}
609		}
610	
611		differences := objects(t, reconciliation, "differences")
612		wantTypes := []string{"timing", "amount_mismatch", "missing_in_ledger", "missing_in_statement"}
613		if len(differences) != len(wantTypes) {
614			t.Fatalf("expected four differences, got %v", differences)
615		}
616		var explained int64
617		for index, difference := range differences {
618			if text(t, difference, "type") != wantTypes[index] {
619				t.Fatalf("difference %d is %v, want %s", index, difference["type"], wantTypes[index])
620			}
621			explained += integer(t, difference, "difference_minor")
622		}
623		if explained != integer(t, reconciliation, "difference_minor") {
624			t.Fatalf("differences explain %d but the period difference is %v", explained, reconciliation["difference_minor"])
625		}
626		if text(t, differences[0], "statement_line_id") != "s2" || text(t, differences[0], "ledger_line_id") != "jv-2#1" {
627			t.Fatalf("timing pair is %v", differences[0])
628		}
629		if integer(t, differences[1], "difference_minor") != 5000 {
630			t.Fatalf("amount mismatch is %v", differences[1])
631		}
632		// A ledger line with no statement line contributes its statement-side
633		// equivalent, so a missing credit of 12000 shows up as +12000.
634		if integer(t, differences[3], "difference_minor") != 12000 {
635			t.Fatalf("missing_in_statement is %v", differences[3])
636		}
637		if integer(t, differences[3], "ledger_amount_minor") != -12000 {
638			t.Fatalf("missing_in_statement ledger amount is %v", differences[3])
639		}
640	
641		// A frozen reconciliation is durable and readable.
642		stored := client.ok("/reconciliations/rec-1")
643		if integer(t, stored, "difference_minor") != 24000 || len(objects(t, stored, "differences")) != 4 {
644			t.Fatalf("stored reconciliation is %v", stored)
645		}
646		client.expect(request{method: http.MethodGet, path: "/reconciliations/rec-9"}, 404, "not_found", "")
647	
648		balance := client.ok("/accounts/1100/balance?as_of=2024-03-31")
649		if integer(t, balance, "debit_minor") != 125000 || integer(t, balance, "credit_minor") != 62000 {
650			t.Fatalf("ledger balance is %v", balance)
651		}
652		if integer(t, balance, "net_minor") != integer(t, reconciliation, "ledger_net_minor") {
653			t.Fatalf("ledger net %v disagrees with the balance %v", reconciliation["ledger_net_minor"], balance["net_minor"])
654		}
655	
656		// A fully matched statement reports balanced with no differences.
657		client.created("/accounts", accountBody("1200", "Savings", "asset", "CNY"))
658		client.created("/journals", `{
659			"id":"jv-6","date":"2024-05-04",
660			"lines":[
661				{"account_id":"1200","side":"debit","amount_minor":40000,"reference":"T-1"},
662				{"account_id":"4000","side":"credit","amount_minor":40000,"reference":"T-1"}
663			]}`)
664		client.created("/statements", `{
665			"id":"st-2","account_id":"1200","currency":"CNY",
666			"period":{"start":"2024-05-01","end":"2024-05-31"},
667			"opening_balance_minor":0,"closing_balance_minor":40000,
668			"lines":[{"id":"s1","date":"2024-05-04","amount_minor":40000,"reference":"T-1"}]}`)
669		balanced := client.created("/reconciliations", `{"id":"rec-2","statement_id":"st-2"}`)
670		if text(t, balanced, "status") != "balanced" || integer(t, balanced, "difference_minor") != 0 {
671			t.Fatalf("balanced reconciliation is %v", balanced)
672		}
673		if len(objects(t, balanced, "differences")) != 0 {
674			t.Fatalf("balanced reconciliation has differences: %v", balanced["differences"])
675		}
676		if integer(t, balanced, "matched_count") != 1 {
677			t.Fatalf("balanced reconciliation matched %v", balanced["matched_count"])
678		}
679	}
