		"lines":[{"id":"s1","date":"2024-03-05","amount_minor":100000,"reference":"INV-1"}]}`)
	frozen := client.created("/reconciliations", `{"id":"rec-1","statement_id":"st-1"}`)
	if text(t, frozen, "status") != "balanced" {
